-- Table: accounting_period_closing_detail
-- Source: accounting_admin_db.sql (6. Accounting expense, reconciliation, and period closing)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS accounting_period_closing_detail (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    closing_id       BIGINT NOT NULL REFERENCES accounting_period_closing(id) ON DELETE CASCADE,
    line_number      INTEGER NOT NULL CHECK (line_number > 0),
    coa_id           BIGINT NOT NULL REFERENCES masterdata_coa(id),
    debit_balance    NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (debit_balance >= 0),
    credit_balance   NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (credit_balance >= 0),
    closing_balance  NUMERIC(18,2) NOT NULL DEFAULT 0,
    UNIQUE (closing_id, line_number)
);
